insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Modern','mcq','medium','The Champaran Satyagraha (1917), Mahatma Gandhi''s first satyagraha within India, was directed against which system of forced indigo cultivation imposed on peasants?','{}'::jsonb,'[{"id": "a", "body": "Tinkathia system", "isCorrect": true}, {"id": "b", "body": "Permanent Settlement", "isCorrect": false}, {"id": "c", "body": "Ryotwari System", "isCorrect": false}, {"id": "d", "body": "Mahalwari System", "isCorrect": false}]'::jsonb,2,0.66,'The Tinkathia system forced Champaran peasants to grow indigo on 3/20th (roughly 3 kathas per bigha) of their land for European planters, at prices fixed by the planters. Gandhi''s 1917 inquiry into these grievances was his first satyagraha on Indian soil. The Permanent Settlement, Ryotwari and Mahalwari systems are colonial land-revenue arrangements, not cultivation mandates, and are unrelated to the Champaran grievance.','modern-champaran-satyagraha-1917','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on Gandhi''s early movements in India.','draft'),
('upsc','History','Modern','mcq','medium','The Non-Cooperation Movement (1920-22) was called off by Mahatma Gandhi in the immediate aftermath of which incident?','{}'::jsonb,'[{"id": "a", "body": "Jallianwala Bagh massacre", "isCorrect": false}, {"id": "b", "body": "Chauri Chaura incident", "isCorrect": true}, {"id": "c", "body": "Moplah Rebellion", "isCorrect": false}, {"id": "d", "body": "Kakori Conspiracy", "isCorrect": false}]'::jsonb,2,0.66,'Gandhi withdrew the Non-Cooperation Movement in February 1922 after a violent mob at Chauri Chaura (United Provinces) killed 22 policemen, which he felt violated the movement''s commitment to non-violence. The Jallianwala Bagh massacre (1919) predates and helped provoke the movement rather than end it; the Moplah Rebellion (1921) was a separate, communally-inflected uprising in Malabar; the Kakori Conspiracy (1925) was a later revolutionary action unconnected to the NCM''s withdrawal.','modern-non-cooperation-chauri-chaura','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Non-Cooperation Movement.','draft'),
('upsc','History','Modern','mcq','medium','The Indian National Congress formally split into ''Moderate'' and ''Extremist'' factions at which session, often referred to as the Surat Split?','{}'::jsonb,'[{"id": "a", "body": "Calcutta Session, 1906", "isCorrect": false}, {"id": "b", "body": "Surat Session, 1907", "isCorrect": true}, {"id": "c", "body": "Nagpur Session, 1920", "isCorrect": false}, {"id": "d", "body": "Lahore Session, 1929", "isCorrect": false}]'::jsonb,2,0.66,'The Surat Session of 1907 saw the open split between the Moderates (led by figures like Gokhale) and Extremists (led by Tilak and others) over leadership and methods. The Calcutta Session (1906) had earlier adopted the Swadeshi/Boycott resolutions but did not itself produce the split; the Nagpur Session (1920) adopted the Non-Cooperation programme; the Lahore Session (1929) passed the Purna Swaraj resolution.','modern-surat-split-1907','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Moderate-Extremist split.','draft'),
('upsc','History','Modern','mcq','medium','The All India Muslim League, founded in 1906 at Dacca, had which person appointed as its first President?','{}'::jsonb,'[{"id": "a", "body": "Muhammad Ali Jinnah", "isCorrect": false}, {"id": "b", "body": "Nawab Salimullah Khan", "isCorrect": false}, {"id": "c", "body": "Aga Khan III", "isCorrect": true}, {"id": "d", "body": "Syed Ahmed Khan", "isCorrect": false}]'::jsonb,2,0.66,'Aga Khan III was elected the first President of the All India Muslim League at its founding in Dacca in December 1906. Nawab Salimullah Khan hosted and was a key organiser of the founding meeting but was not its first president. Jinnah joined and later led the League, but only years afterward. Syed Ahmed Khan, associated with the Aligarh movement, had died in 1898, before the League was formed.','modern-muslim-league-founding-1906','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on communal politics and the founding of the Muslim League.','draft'),
('upsc','History','Modern','mcq','medium','Lord Curzon''s partition of Bengal, announced in 1905, was annulled by the colonial government in which year?','{}'::jsonb,'[{"id": "a", "body": "1908", "isCorrect": false}, {"id": "b", "body": "1911", "isCorrect": true}, {"id": "c", "body": "1919", "isCorrect": false}, {"id": "d", "body": "1935", "isCorrect": false}]'::jsonb,2,0.66,'The partition of Bengal was annulled in 1911, announced at the Delhi Durbar, following sustained Swadeshi-era agitation. 1908 falls within the agitation period itself, not the annulment; 1919 and 1935 relate to unrelated later constitutional reforms (Government of India Acts).','modern-partition-of-bengal-annulment','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Swadeshi Movement and partition of Bengal.','draft'),
('upsc','History','Modern','mcq','medium','In the Individual Satyagraha launched by Mahatma Gandhi in October 1940, who was selected as the first individual satyagrahi?','{}'::jsonb,'[{"id": "a", "body": "Jawaharlal Nehru", "isCorrect": false}, {"id": "b", "body": "Vinoba Bhave", "isCorrect": true}, {"id": "c", "body": "Rajendra Prasad", "isCorrect": false}, {"id": "d", "body": "Sardar Vallabhbhai Patel", "isCorrect": false}]'::jsonb,2,0.66,'Vinoba Bhave was chosen by Gandhi as the first individual satyagrahi in October 1940, offering token anti-war resistance on an individual basis rather than through mass mobilisation. Jawaharlal Nehru was selected as the second satyagrahi in the sequence, not the first -- a detail that is a common source of confusion.','modern-individual-satyagraha-1940','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Individual Satyagraha.','draft'),
('upsc','History','Ancient','mcq','medium','Bindusara, the second Mauryan emperor and father of Ashoka, is referred to in Greek accounts by which title/name?','{}'::jsonb,'[{"id": "a", "body": "Sandrocottus", "isCorrect": false}, {"id": "b", "body": "Amitrochates", "isCorrect": true}, {"id": "c", "body": "Devanampiya", "isCorrect": false}, {"id": "d", "body": "Piyadasi", "isCorrect": false}]'::jsonb,2,0.66,'Greek writers referred to Bindusara as ''Amitrochates'' (a Hellenised rendering of ''Amitraghata'', roughly ''slayer of foes''). ''Sandrocottus'' is the Greek name for Chandragupta Maurya, Bindusara''s father, not Bindusara himself. ''Devanampiya'' and ''Piyadasi'' are epithets associated with Ashoka in his edicts.','ancient-bindusara-mauryan-empire','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Mauryan Empire.','draft'),
('upsc','History','Ancient','mcq','medium','The Saka Era, used alongside the Gregorian calendar in the Indian national calendar, is traditionally dated to 78 CE and associated with the accession of which ruler?','{}'::jsonb,'[{"id": "a", "body": "Kanishka", "isCorrect": true}, {"id": "b", "body": "Chandragupta II", "isCorrect": false}, {"id": "c", "body": "Kadphises I", "isCorrect": false}, {"id": "d", "body": "Rudradaman I", "isCorrect": false}]'::jsonb,2,0.66,'The Saka Era of 78 CE is conventionally linked to the accession of the Kushan ruler Kanishka, despite the era''s name suggesting a Saka origin. Rudradaman I was a Western Kshatrapa (Saka) ruler and a plausible-sounding distractor precisely because of the era''s name, but he is not the ruler credited with its introduction. Chandragupta II and Kadphises I belong to different dynasties and periods.','ancient-saka-era-kanishka','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Kushans.','draft'),
('upsc','History','Ancient','mcq','medium','According to the Nashik Prashasti inscription of Gautami Balashri, her son Gautamiputra Satakarni of the Satavahana dynasty defeated which Saka ruler?','{}'::jsonb,'[{"id": "a", "body": "Rudradaman I", "isCorrect": false}, {"id": "b", "body": "Menander", "isCorrect": false}, {"id": "c", "body": "Kanishka", "isCorrect": false}, {"id": "d", "body": "Nahapana", "isCorrect": true}]'::jsonb,2,0.66,'The Nashik Prashasti records Gautamiputra Satakarni''s defeat of the Western Kshatrapa (Saka) ruler Nahapana. Rudradaman I is a related but distinct figure -- in fact he later defeated the Satavahanas in turn, the reverse of this event, which makes him a common point of confusion here. Menander was an earlier Indo-Greek king, and Kanishka was a Kushan ruler, unconnected to this specific engagement.','ancient-gautamiputra-satakarni-nahapana','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Satavahanas.','draft'),
('upsc','History','Ancient','mcq','medium','Nalanda University, a major centre of ancient learning, is traditionally credited as having been founded under the patronage of which Gupta ruler?','{}'::jsonb,'[{"id": "a", "body": "Samudragupta", "isCorrect": false}, {"id": "b", "body": "Chandragupta II", "isCorrect": false}, {"id": "c", "body": "Kumaragupta I", "isCorrect": true}, {"id": "d", "body": "Skandagupta", "isCorrect": false}]'::jsonb,2,0.66,'Nalanda''s founding is traditionally credited to Kumaragupta I in the early fifth century CE. Samudragupta and Chandragupta II preceded him and are associated with military expansion and the ''Vikramaditya'' title respectively, while Skandagupta is chiefly remembered for repelling Huna invasions -- none of the three are credited with Nalanda''s founding.','ancient-nalanda-university-founding','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Gupta Empire and centres of learning.','draft'),
('upsc','History','Ancient','mcq','medium','Chandragupta II, who adopted the title ''Vikramaditya'', is traditionally associated with a court that included nine distinguished scholars known as the:','{}'::jsonb,'[{"id": "a", "body": "Ashtapradhan", "isCorrect": false}, {"id": "b", "body": "Navaratnas", "isCorrect": true}, {"id": "c", "body": "Saptarishis", "isCorrect": false}, {"id": "d", "body": "Panchayatan", "isCorrect": false}]'::jsonb,2,0.66,'Chandragupta II''s court is traditionally associated with the ''Navaratnas'' (Nine Gems), a group of nine eminent scholars said to include Kalidasa. ''Ashtapradhan'' refers to the eight-member council of ministers in the much later Maratha administration under Shivaji, an unrelated era. ''Saptarishis'' refers to the seven sages of Puranic tradition, and ''Panchayatan'' is a term from temple architecture, not court scholarship.','ancient-chandragupta-ii-navaratnas','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Gupta Empire, Chandragupta II.','draft'),
('upsc','History','Ancient','mcq','medium','Megasthenes, the Greek ambassador whose account ''Indica'' provides valuable information on Mauryan India, was sent to Chandragupta Maurya''s court by which Hellenistic ruler?','{}'::jsonb,'[{"id": "a", "body": "Alexander the Great", "isCorrect": false}, {"id": "b", "body": "Seleucus I Nicator", "isCorrect": true}, {"id": "c", "body": "Antiochus I", "isCorrect": false}, {"id": "d", "body": "Ptolemy I", "isCorrect": false}]'::jsonb,2,0.66,'Megasthenes was sent as ambassador to Chandragupta Maurya''s court by Seleucus I Nicator, one of Alexander''s successors, following a treaty between the two rulers. Alexander the Great himself had died (323 BCE) before this embassy took place, making him a tempting but incorrect answer given his general association with this period of Indo-Greek contact. Antiochus I and Ptolemy I were contemporaries of Seleucus but not the ones who dispatched Megasthenes.','ancient-megasthenes-seleucus-indica','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Mauryan Empire and foreign accounts.','draft'),
('upsc','History','Ancient','mcq','medium','The Sangam-era Tamil epic ''Silappadikaram'', centred on the character Kannagi, is attributed to which author?','{}'::jsonb,'[{"id": "a", "body": "Sattanar", "isCorrect": false}, {"id": "b", "body": "Thiruvalluvar", "isCorrect": false}, {"id": "c", "body": "Ilango Adigal", "isCorrect": true}, {"id": "d", "body": "Nakkirar", "isCorrect": false}]'::jsonb,2,0.66,'The Silappadikaram is attributed to Ilango Adigal. Sattanar is the traditional author of the ''Manimekalai'', a companion epic continuing the story of Kannagi''s daughter, and is a common point of confusion given the thematic link between the two works. Thiruvalluvar is associated with the separate ethical text ''Tirukkural'', and Nakkirar is a different Sangam-era poet.','ancient-silappadikaram-sangam-literature','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Sangam Age and Tamil literature.','draft')
